-- claves naturales únicas, idempotente INSERT ... ON CONFLICT).
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Versión del catálogo (ADR-03)
-- ---------------------------------------------------------------------------
INSERT INTO public.catalogo_version (version, fuente)
VALUES (
  2,
  'Catálogo electoral Rumiñahui (Pichincha) — CNE, corte 14/10/2026. Recintos: 22, JRV: 298. Fuente: data/catalogo-ruminahui.csv.'
)
ON CONFLICT (version) DO UPDATE
SET fuente = EXCLUDED.fuente;

-- ---------------------------------------------------------------------------
-- Provincia (Pichincha, código 17)
-- ---------------------------------------------------------------------------
INSERT INTO public.provincias (id, codigo, nombre)
VALUES ('10000000-0000-4000-8000-000000000001', '17', 'Pichincha')
ON CONFLICT (codigo) DO UPDATE SET nombre = EXCLUDED.nombre;

-- ---------------------------------------------------------------------------
-- Recintos (22) y JRV (298) desde el CSV
-- ---------------------------------------------------------------------------
