-- ---------------------------------------------------------------------------
INSERT INTO public.candidatos (id, organizacion_id, dignidad, nombre)
SELECT v.id, o.id, v.dignidad::public.dignidad, v.nombre
FROM (VALUES
  ('50000000-0000-4000-8000-000000000011'::uuid, 'Alianza Valle Vivo', 'ALCALDIA',   'Candidato Alcaldía - Alianza Valle Vivo'),
  ('50000000-0000-4000-8000-000000000021'::uuid, 'Alianza Valle Vivo', 'PREFECTURA', 'Candidato Prefectura - Alianza Valle Vivo'),
  ('50000000-0000-4000-8000-000000000012'::uuid, 'Frente Unidad Rumiñahui', 'ALCALDIA',   'Candidato Alcaldía - Frente Unidad Rumiñahui'),
  ('50000000-0000-4000-8000-000000000022'::uuid, 'Frente Unidad Rumiñahui', 'PREFECTURA', 'Candidato Prefectura - Frente Unidad Rumiñahui'),
  ('50000000-0000-4000-8000-000000000013'::uuid, 'Pacto Futuro Común', 'ALCALDIA',   'Candidato Alcaldía - Pacto Futuro Común'),
  ('50000000-0000-4000-8000-000000000023'::uuid, 'Pacto Futuro Común', 'PREFECTURA', 'Candidato Prefectura - Pacto Futuro Común'),
  ('50000000-0000-4000-8000-000000000014'::uuid, 'Renovación Cívica Andina', 'ALCALDIA',   'Candidato Alcaldía - Renovación Cívica Andina'),
  ('50000000-0000-4000-8000-000000000024'::uuid, 'Renovación Cívica Andina', 'PREFECTURA', 'Candidato Prefectura - Renovación Cívica Andina'),
  ('50000000-0000-4000-8000-000000000015'::uuid, 'Movimiento Horizonte Ciudadano', 'ALCALDIA',   'Candidato Alcaldía - Movimiento Horizonte Ciudadano'),
  ('50000000-0000-4000-8000-000000000025'::uuid, 'Movimiento Horizonte Ciudadano', 'PREFECTURA', 'Candidato Prefectura - Movimiento Horizonte Ciudadano')
) AS v(id, organizacion_nombre, dignidad, nombre)
JOIN public.organizaciones o ON o.nombre = v.organizacion_nombre
ON CONFLICT (organizacion_id, dignidad) DO UPDATE
SET nombre = EXCLUDED.nombre;
